WITH esperadas AS (SELECT 'flota_cb2_pilotos_reportados' tabla UNION ALL SELECT 'flota_cb2_consumo_piloto_reportado' UNION ALL SELECT 'flota_cb2_pilotos_equivalencias') SELECT e.*,t.ENGINE,t.TABLE_COLLATION FROM esperadas e LEFT JOIN information_schema.TABLES t ON t.TABLE_SCHEMA=DATABASE() AND t.TABLE_NAME=e.tabla WHERE t.TABLE_NAME IS NULL OR t.ENGINE<>'InnoDB' OR t.TABLE_COLLATION<>'utf8mb4_bin';
WITH requeridos AS (SELECT 'flota_cb2_pilotos_reportados' tabla,'PRIMARY' indice,'id' columnas,0 no_unico UNION ALL SELECT 'flota_cb2_pilotos_reportados','uq_cb2pr_ambito','empresa_id,id',0 UNION ALL SELECT 'flota_cb2_pilotos_reportados','uq_cb2pr_nombre','empresa_id,normalizacion_version,nombre_hash',0 UNION ALL SELECT 'flota_cb2_consumo_piloto_reportado','PRIMARY','empresa_id,proveedor_id,consumo_id',0 UNION ALL SELECT 'flota_cb2_consumo_piloto_reportado','ix_cb2cpr_piloto','empresa_id,piloto_reportado_id',1 UNION ALL SELECT 'flota_cb2_pilotos_equivalencias','PRIMARY','empresa_id,normalizacion_version,nombre_hash',0 UNION ALL SELECT 'flota_cb2_consumos','uq_cb2c_ambito','empresa_id,proveedor_id,id',0 UNION ALL SELECT 'empresas','PRIMARY','id',0 UNION ALL SELECT 'usuarios','PRIMARY','id',0 UNION ALL SELECT 'empleados','PRIMARY','id',0) SELECT r.*,'INDICE_INCOMPATIBLE_O_FALTANTE' problema FROM requeridos r WHERE NOT EXISTS(SELECT 1 FROM information_schema.STATISTICS s WHERE s.TABLE_SCHEMA=DATABASE() AND s.TABLE_NAME=r.tabla AND s.INDEX_NAME=r.indice GROUP BY s.INDEX_NAME HAVING MAX(s.NON_UNIQUE)=r.no_unico AND MIN(s.NON_UNIQUE)=r.no_unico AND GROUP_CONCAT(s.COLUMN_NAME ORDER BY s.SEQ_IN_INDEX)=r.columnas AND SUM(s.SUB_PART IS NOT NULL)=0 AND MIN(s.INDEX_TYPE)='BTREE');
WITH requeridas AS (SELECT 'flota_cb2_pilotos_reportados' tabla,'fk_cb2pr_empresa' nombre,'empresa_id' columnas,'empresas' padre,'id' columnas_padre UNION ALL SELECT 'flota_cb2_pilotos_reportados','fk_cb2pr_actor','creado_por','usuarios','id' UNION ALL SELECT 'flota_cb2_consumo_piloto_reportado','fk_cb2cpr_consumo','empresa_id,proveedor_id,consumo_id','flota_cb2_consumos','empresa_id,proveedor_id,id' UNION ALL SELECT 'flota_cb2_consumo_piloto_reportado','fk_cb2cpr_piloto','empresa_id,piloto_reportado_id','flota_cb2_pilotos_reportados','empresa_id,id' UNION ALL SELECT 'flota_cb2_pilotos_equivalencias','fk_cb2pe_empresa','empresa_id','empresas','id' UNION ALL SELECT 'flota_cb2_pilotos_equivalencias','fk_cb2pe_empleado','empleado_id','empleados','id' UNION ALL SELECT 'flota_cb2_pilotos_equivalencias','fk_cb2pe_reportado','empresa_id,piloto_reportado_id','flota_cb2_pilotos_reportados','empresa_id,id' UNION ALL SELECT 'flota_cb2_pilotos_equivalencias','fk_cb2pe_actor','confirmado_por','usuarios','id') SELECT e.*,'FK_INCOMPATIBLE_O_FALTANTE' problema FROM requeridas e WHERE NOT EXISTS(SELECT 1 FROM information_schema.REFERENTIAL_CONSTRAINTS r JOIN information_schema.KEY_COLUMN_USAGE k ON k.CONSTRAINT_SCHEMA=r.CONSTRAINT_SCHEMA AND k.TABLE_NAME=r.TABLE_NAME AND k.CONSTRAINT_NAME=r.CONSTRAINT_NAME WHERE r.CONSTRAINT_SCHEMA=DATABASE() AND r.TABLE_NAME=e.tabla AND r.CONSTRAINT_NAME=e.nombre AND r.REFERENCED_TABLE_NAME=e.padre AND r.DELETE_RULE='RESTRICT' AND r.UPDATE_RULE='RESTRICT' AND k.REFERENCED_TABLE_SCHEMA=DATABASE() GROUP BY r.CONSTRAINT_NAME HAVING GROUP_CONCAT(k.COLUMN_NAME ORDER BY k.ORDINAL_POSITION)=e.columnas AND GROUP_CONCAT(k.REFERENCED_COLUMN_NAME ORDER BY k.ORDINAL_POSITION)=e.columnas_padre);
WITH esperadas AS (SELECT 'flota_cb2_pilotos_reportados' tabla,'ck_cb2pr_version' nombre UNION ALL SELECT 'flota_cb2_pilotos_reportados','ck_cb2pr_estado' UNION ALL SELECT 'flota_cb2_pilotos_reportados','ck_cb2pr_nombre' UNION ALL SELECT 'flota_cb2_pilotos_equivalencias','ck_cb2pe_revision' UNION ALL SELECT 'flota_cb2_pilotos_equivalencias','ck_cb2pe_version' UNION ALL SELECT 'flota_cb2_pilotos_equivalencias','ck_cb2pe_destino' UNION ALL SELECT 'flota_cb2_pilotos_equivalencias','ck_cb2pe_nombre') SELECT e.*,'CHECK_FALTANTE' problema FROM esperadas e LEFT JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=DATABASE() AND c.TABLE_NAME=e.tabla AND c.CONSTRAINT_NAME=e.nombre WHERE c.CONSTRAINT_NAME IS NULL;
SELECT TABLE_NAME,CONSTRAINT_NAME,CHECK_CLAUSE FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME IN('flota_cb2_pilotos_reportados','flota_cb2_consumo_piloto_reportado','flota_cb2_pilotos_equivalencias') ORDER BY TABLE_NAME,CONSTRAINT_NAME;
SELECT TABLE_NAME,COLUMN_NAME,COLUMN_TYPE,IS_NULLABLE,COLUMN_DEFAULT,EXTRA,COLLATION_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN('flota_cb2_pilotos_reportados','flota_cb2_consumo_piloto_reportado','flota_cb2_pilotos_equivalencias') ORDER BY TABLE_NAME,ORDINAL_POSITION;
SELECT TABLE_NAME,CONSTRAINT_NAME,UNIQUE_CONSTRAINT_NAME,REFERENCED_TABLE_NAME,DELETE_RULE,UPDATE_RULE FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME IN('flota_cb2_pilotos_reportados','flota_cb2_consumo_piloto_reportado','flota_cb2_pilotos_equivalencias');
